import { NextResponse } from "next/server";
import { AiError } from "@/lib/ai/openai";
import { createAnamSessionToken, isAnamEnabled } from "@/lib/ai/anam";
import { requireChatbotAccess } from "@/lib/ai/chatbotAccess";

export const runtime = "nodejs";
export const maxDuration = 30;

/**
 * Starts the assistant's live avatar (the Anam clone persona).
 *
 * Returns a short-lived session token for the browser's WebRTC stream; the
 * Anam API key stays on the server. The persona only renders face and voice -
 * what she says is generated by OpenAI (see `src/lib/ai/anam.ts`).
 * Open to guests and rate limited, like the rest of the assistant.
 */
export async function POST(request: Request) {
  if (!isAnamEnabled()) {
    return NextResponse.json({ error: "アバターが設定されていません。" }, { status: 503 });
  }

  try {
    const body = await request.json().catch(() => ({}));
    const gate = await requireChatbotAccess(request, "avatar", String(body?.labId ?? ""));
    if (!gate.ok) {
      return NextResponse.json(
        { error: gate.error },
        { status: gate.status, headers: { "Retry-After": String(gate.retryAfterSec) } },
      );
    }
    const sessionToken = await createAnamSessionToken();
    return NextResponse.json({ sessionToken }, { headers: { "Cache-Control": "no-store" } });
  } catch (e) {
    if (e instanceof AiError) {
      return NextResponse.json({ error: e.message, retryable: e.retryable }, { status: e.status });
    }
    return NextResponse.json(
      { error: e instanceof Error ? e.message : "アバターを開始できませんでした。" },
      { status: 500 },
    );
  }
}
